const React = require('react');
const TestRenderer = require('react-test-renderer');
let useAgentChat;
try {
  ({ useAgentChat } = require('agents/chat/react'));
} catch (e) {
  console.error('ERROR: cannot load agents/chat/react: ' + (e && e.message));
  process.exit(2);
}
globalThis.IS_REACT_ACT_ENVIRONMENT = true;
const watchdog = setTimeout(() => {
  console.error('ERROR: timed out');
  process.exit(2);
}, 60000);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const target = new EventTarget();
const sent = [];
const agent = {
  agent: 'chat',
  name: 'ludion',
  getHttpUrl: () => 'http://localhost:3000/agents/chat/ludion',
  send: (data) => { sent.push(data); },
  addEventListener: target.addEventListener.bind(target),
  removeEventListener: target.removeEventListener.bind(target)
};
const frame = (id, chunk) =>
  target.dispatchEvent(new MessageEvent('message', {
    data: JSON.stringify({
      type: 'cf_agent_use_chat_response',
      id,
      body: chunk ? JSON.stringify(chunk) : '',
      done: chunk === null
    })
  }));

const toolCalls = [];
let chat = null;
function App() {
  chat = useAgentChat({
    agent,
    getInitialMessages: null,
    messages: [],
    resume: false,
    onToolCall: ({ toolCall }) => { toolCalls.push(toolCall.toolCallId); }
  });
  return null;
}

async function main() {
  await React.act(async () => {
    TestRenderer.create(React.createElement(App));
    await sleep(20);
  });
  if (!chat) throw new Error('hook did not render');
  let sendPromise;
  await React.act(async () => {
    sendPromise = chat.sendMessage({ text: 'Where am I?' });
    await sleep(30);
  });
  const request = sent.map((s) => JSON.parse(s)).find((m) => m.type === 'cf_agent_use_chat_request');
  if (!request) throw new Error('no chat request sent: ' + JSON.stringify(sent));
  // a server tool and a client tool both arrive mid-stream; only the server one gets an output
  await React.act(async () => {
    frame(request.id, { type: 'start', messageId: 'a1' });
    frame(request.id, { type: 'tool-input-available', toolCallId: 'tc-server', toolName: 'search', input: { q: 'weather' } });
    frame(request.id, { type: 'tool-input-available', toolCallId: 'tc-client', toolName: 'getLocation', input: {} });
    await sleep(50);
  });
  const midStream = [...toolCalls];
  const midStatus = chat.status;
  await React.act(async () => {
    frame(request.id, { type: 'tool-output-available', toolCallId: 'tc-server', output: { forecast: 'sunny' } });
    frame(request.id, { type: 'finish' });
    frame(request.id, null);
    await sendPromise;
    await sleep(50);
  });
  const afterEnd = [...toolCalls];
  clearTimeout(watchdog);
  const info = 'mid-stream=' + JSON.stringify(midStream) + ' (status ' + midStatus + ') after-end=' + JSON.stringify(afterEnd);
  if (midStream.length === 0 && JSON.stringify(afterEnd) === JSON.stringify(['tc-client'])) {
    console.log('OK: onToolCall waited for the stream to end and fired only for the client tool; ' + info);
    process.exit(0);
  }
  if (midStream.includes('tc-server')) {
    console.error('FAIL: useAgentChat onToolCall fired for a server tool while the response was still streaming');
    console.error(info);
    process.exit(1);
  }
  console.error('ERROR: unexpected onToolCall calls; ' + info);
  process.exit(2);
}
main().catch((e) => {
  console.error('ERROR: ' + ((e && e.stack) || e));
  process.exit(2);
});

